package com.example.quanlybaotri.shared.storage;

import com.example.quanlybaotri.shared.api.ApiException;
import java.io.*;
import java.util.*;
import java.util.zip.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.multipart.MultipartFile;

public final class FilePolicy {
    private static final long MIB=1024L*1024L;
    private static final Set<String> IMAGE=Set.of("image/jpeg","image/png","image/webp"), VIDEO=Set.of("video/mp4","video/webm"), DOCUMENT=Set.of("application/pdf","application/msword","application/vnd.ms-excel","application/vnd.openxmlformats-officedocument.wordprocessingml.document","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    private FilePolicy(){}
    public static ValidatedFile validate(MultipartFile file){if(file==null||file.isEmpty())throw invalid("INVALID_FILE_SIZE","Tệp phải có dung lượng lớn hơn 0");String name=safeName(file.getOriginalFilename()),type;try{type=detect(file,extension(name));}catch(IOException ex){throw invalid("INVALID_FILE_TYPE","Không thể nhận diện định dạng tệp");}long max=IMAGE.contains(type)?10*MIB:VIDEO.contains(type)?200*MIB:DOCUMENT.contains(type)?25*MIB:0;if(max==0)throw invalid("INVALID_FILE_TYPE","Chỉ hỗ trợ JPG, PNG, WebP, MP4, WebM, PDF, DOC, DOCX, XLS và XLSX");if(file.getSize()>max)throw invalid("INVALID_FILE_SIZE","Tệp vượt quá giới hạn dung lượng cho định dạng này");return new ValidatedFile(name,type,IMAGE.contains(type)?"IMAGE":VIDEO.contains(type)?"VIDEO":type.equals("application/pdf")?"PDF":"DOWNLOAD");}
    private static String detect(MultipartFile file,String ext)throws IOException{byte[] h=new byte[16];int count;try(InputStream in=new BufferedInputStream(file.getInputStream())){count=in.read(h);}if(count>=3&&u(h[0])==255&&u(h[1])==216&&u(h[2])==255)return ext(ext,"jpg","jpeg","image/jpeg");if(count>=8&&match(h,new int[]{137,80,78,71,13,10,26,10}))return ext(ext,"png",null,"image/png");if(count>=12&&ascii(h,0,"RIFF")&&ascii(h,8,"WEBP"))return ext(ext,"webp",null,"image/webp");if(count>=5&&ascii(h,0,"%PDF-"))return ext(ext,"pdf",null,"application/pdf");if(count>=8&&ascii(h,4,"ftyp"))return ext(ext,"mp4",null,"video/mp4");if(count>=4&&match(h,new int[]{26,69,223,163}))return ext(ext,"webm",null,"video/webm");if(count>=8&&match(h,new int[]{208,207,17,224,161,177,26,225})){if(ext.equals("doc"))return "application/msword";if(ext.equals("xls"))return "application/vnd.ms-excel";}if(count>=4&&u(h[0])==80&&u(h[1])==75)return ooxml(file,ext);return "application/octet-stream";}
    private static String ooxml(MultipartFile file,String ext)throws IOException{boolean word=false,xls=false;try(ZipInputStream zip=new ZipInputStream(file.getInputStream())){ZipEntry e;int n=0;while((e=zip.getNextEntry())!=null&&n++<100){word|=e.getName().startsWith("word/");xls|=e.getName().startsWith("xl/");}}if(word&&ext.equals("docx"))return "application/vnd.openxmlformats-officedocument.wordprocessingml.document";if(xls&&ext.equals("xlsx"))return "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";return "application/octet-stream";}
    private static String ext(String actual,String a,String b,String type){return actual.equals(a)||(b!=null&&actual.equals(b))?type:"application/octet-stream";} private static String extension(String n){int i=n.lastIndexOf('.');return i<0?"":n.substring(i+1).toLowerCase(Locale.ROOT);} public static String safeName(String n){if(n==null||n.isBlank())return "attachment";String v=n.replace('\\','/');v=v.substring(v.lastIndexOf('/')+1).replaceAll("[\\r\\n]","_");return v.substring(0,Math.min(255,v.length()));} private static boolean ascii(byte[] v,int o,String x){for(int i=0;i<x.length();i++)if(o+i>=v.length||v[o+i]!=(byte)x.charAt(i))return false;return true;}private static boolean match(byte[] v,int[] x){for(int i=0;i<x.length;i++)if(u(v[i])!=x[i])return false;return true;}private static int u(byte v){return v&255;}private static ApiException invalid(String c,String m){return new ApiException(HttpStatus.BAD_REQUEST,c,m);}public record ValidatedFile(String name,String contentType,String previewKind){}
}
